import{_ as o,o as t,c as a,a2 as r}from"./chunks/framework.BZO4qERu.js";const c=JSON.parse('{"title":"Desktop","description":"","frontmatter":{},"headers":[],"relativePath":"ru/self-hosted/desktop.md","filePath":"ru/self-hosted/desktop.md","lastUpdated":1792323081000}'),l={name:"ru/self-hosted/desktop.md"};function s(i,e,p,h,d,n){return t(),a("div",null,[...e[0]||(e[0]=[r('<h1 id="desktop" tabindex="-1">Desktop <a class="header-anchor" href="#desktop" aria-label="Permalink to &quot;Desktop&quot;">​</a></h1><p>Memoh Desktop — нативный клиент для Memoh Cloud или самостоятельно развёрнутого сервера Memoh. Он упаковывает тот же клиентский интерфейс в оболочку Electron с нативными окнами, треем, меню и поддержкой клавиатуры, а также может зарегистрировать компьютер, на котором работает, как <strong>Computer</strong> (компьютер), доступный вашим Bot.</p><p>Desktop <strong>не</strong> запускает собственный локальный сервер или базу данных. Вы всегда подключаете его к серверу Memoh: либо к <a href="https://memoh.ai" target="_blank" rel="noreferrer">Memoh Cloud</a>, либо к собственному <a href="./docker.html">Server Deploy</a>.</p><h2 id="когда-выбирать-desktop" tabindex="-1">Когда выбирать Desktop <a class="header-anchor" href="#когда-выбирать-desktop" aria-label="Permalink to &quot;Когда выбирать Desktop&quot;">​</a></h2><p>Выбирайте Desktop, если вам нужны:</p><ul><li>нативное окно приложения и системный трей вместо вкладки браузера</li><li>нативные меню и горячие клавиши для повседневной работы с Memoh</li><li>возможность дать серверным Bot доступ к файлам, оболочке и браузеру этого компьютера без отдельного процесса рантайма</li></ul><p>Если вам достаточно изредка заходить из браузера, пользуйтесь веб-клиентом напрямую.</p><h2 id="установка" tabindex="-1">Установка <a class="header-anchor" href="#установка" aria-label="Permalink to &quot;Установка&quot;">​</a></h2><ol><li>Скачайте установщик для своей платформы (macOS DMG, Windows NSIS или Linux AppImage/deb/rpm) со <a href="https://memoh.ai/desktop" target="_blank" rel="noreferrer">страницы загрузки Memoh Desktop</a>.</li><li>Откройте Memoh.</li><li>На экране подключения введите адрес сервера (или выберите Memoh Cloud).</li><li>Войдите под своей учётной записью Memoh.</li></ol><h2 id="подключение-к-серверу" tabindex="-1">Подключение к серверу <a class="header-anchor" href="#подключение-к-серверу" aria-label="Permalink to &quot;Подключение к серверу&quot;">​</a></h2><p>На экране подключения введите адрес сервера и подключитесь:</p><ul><li>«Голый» домен вроде <code>memoh.example.com</code> считается <code>https://</code> (только адреса localhost по умолчанию получают <code>http://</code>).</li><li>Суффикс пути <code>/api</code> добавляется автоматически, если его нет, так что достаточно ввести один домен.</li><li>Прежде чем продолжить, Desktop опрашивает эндпоинт сервера <code>/ping</code> (тайм-аут 5 секунд), а затем переводит вас к входу.</li></ul><p>Переключение на другой сервер сбрасывает локальное состояние входа, поэтому на новом сервере придётся войти заново.</p><h2 id="как-поделиться-этим-компьютером-с-bot" tabindex="-1">Как поделиться этим компьютером с Bot <a class="header-anchor" href="#как-поделиться-этим-компьютером-с-bot" aria-label="Permalink to &quot;Как поделиться этим компьютером с Bot&quot;">​</a></h2><p>Desktop может зарегистрировать машину, на которой работает, как <strong>Computer</strong>, на котором смогут работать серверные Bot, — без отдельного процесса рантайма. Включите <strong>This computer</strong> (этот компьютер), дайте ему имя, и Desktop будет поддерживать соединение в фоне через встроенный Memoh runtime SDK. Учётные данные хранятся в защищённом хранилище операционной системы.</p><p>Доступ выдаётся каждому Bot отдельно, а действия записи и выполнения по умолчанию требуют подтверждения — см. <a href="./../guides/access.html">Контроль доступа</a>.</p><h2 id="чем-управляет-desktop" tabindex="-1">Чем управляет Desktop <a class="header-anchor" href="#чем-управляет-desktop" aria-label="Permalink to &quot;Чем управляет Desktop&quot;">​</a></h2><ul><li>окном приложения, иконкой в трее, поведением при повторном открытии и выходе</li><li>нативными меню, подключёнными к тому же реестру команд, что и в веб-клиенте</li><li>соединением с выбранным сервером и кешированным состоянием входа</li><li>необязательным подключением Remote Runtime для <strong>This computer</strong></li></ul><p>Всё остальное (Bot, сессии, память, рабочие пространства, каналы) живёт на сервере, к которому вы подключились. Рантаймы рабочих пространств настраиваются на стороне сервера; см. <a href="./workspace-backends.html">Бэкенды рабочих пространств</a>.</p>',19)])])}const k=o(l,[["render",s]]);export{c as __pageData,k as default};
